import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Intermediate joins must not all pool into one global OUTPUT_ROWS learning family: the raw transform carries a
 * topology fingerprint of the joined prefix, so only same-topology joins share calibration evidence.
 */
class LmdbFrontierJoinFamilyTopologyTest {

	private static final String STAR_QUERY = """
			SELECT * WHERE {
				?person <urn:test:memberOf> ?organization .
				?person <urn:test:worksAt> ?company .
				?person <urn:test:livesIn> ?city .
			}
			""";

	private static final String PATH_QUERY = """
			SELECT * WHERE {
				?person <urn:test:memberOf> ?organization .
				?organization <urn:test:locatedIn> ?city .
				?city <urn:test:partOf> ?region .
			}
			""";

	@Test
	void intermediateJoinLearningKeysIncludeTopology(@TempDir File dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		config.setFrontierSynopsisBudgetBytes(1024L * 1024L);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			ValueFactory vf = repository.getValueFactory();
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int i = 0; i < 32; i++) {
					var person = vf.createIRI("urn:test:person:" + i);
					var organization = vf.createIRI("urn:test:org:" + i % 4);
					var city = vf.createIRI("urn:test:city:" + i % 8);
					connection.add(person, vf.createIRI("urn:test:memberOf"), organization);
					connection.add(person, vf.createIRI("urn:test:worksAt"), vf.createIRI("urn:test:company:" + i % 4));
					connection.add(person, vf.createIRI("urn:test:livesIn"), city);
					connection.add(organization, vf.createIRI("urn:test:locatedIn"), city);
					connection.add(city, vf.createIRI("urn:test:partOf"), vf.createIRI("urn:test:region:" + i % 2));
				}
				connection.commit();
			}
			assertTrue(store.rebuildFrontierSynopsis() == FrontierSynopsisStatus.READY);

			List<String> starTransforms = intermediateJoinTransforms(repository, STAR_QUERY);
			List<String> pathTransforms = intermediateJoinTransforms(repository, PATH_QUERY);

			assertFalse(starTransforms.isEmpty(), "The three-way star must cost at least one intermediate join");
			assertFalse(pathTransforms.isEmpty(), "The three-way path must cost at least one intermediate join");
			for (String transform : starTransforms) {
				assertTrue(transform.contains("@"),
						"Intermediate-join learning keys must carry a topology fingerprint, got " + transform);
			}
			assertNotEquals(starTransforms, pathTransforms,
					"Structurally different joins must not share one global learning family");
		} finally {
			repository.shutDown();
		}
	}

	private static List<String> intermediateJoinTransforms(SailRepository repository, String query) {
		List<String> transforms = new ArrayList<>();
		try (var connection = repository.getConnection()) {
			Explanation explanation = connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized);
			((TupleExpr) explanation.tupleExpr()).visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(Join node) {
					collect(node);
					super.meet(node);
				}

				private void collect(QueryModelNode node) {
					String encoded = node.getStringMetricPlanned("optimizer.frontierLearningKey");
					FrontierLearningKey key = encoded == null ? null : FrontierLearningKey.parse(encoded);
					if (key != null && "join".equals(key.operatorFamily())) {
						transforms.add(key.rawTransform());
					}
				}
			});
		}
		return transforms;
	}
}
